import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"熱鍵(設定頁面)","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/hotkeys-page.md","filePath":"zh-TW/user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),a={name:"zh-TW/user-guide/settings/hotkeys-page.md"};function l(n,e,c,d,i,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="熱鍵-設定頁面" tabindex="-1">熱鍵(設定頁面) <a class="header-anchor" href="#熱鍵-設定頁面" aria-label="Permalink to &quot;熱鍵(設定頁面)&quot;">​</a></h1><p>三個分頁:<strong>全域</strong>、<strong>外掛動作</strong>、<strong>處理程序黑名單</strong>。每個熱鍵具體做什麼見<a href="./../hotkeys.html">熱鍵</a>頁面——這一篇只講設定介面本身。</p><h2 id="全域" tabindex="-1">全域 <a class="header-anchor" href="#全域" aria-label="Permalink to &quot;全域&quot;">​</a></h2><p><strong>全域快捷鍵</strong>分組:</p><ul><li><strong>顯示/隱藏快速搜尋</strong> —— 錄製控制項;既可以錄製成裸輔助鍵(按兩下模式，預設 <code>Ctrl</code>)，也可以錄製成完整組合鍵。旁邊的<strong>全螢幕應用程式聚焦時仍然回應</strong> —— 核取方塊，預設關閉;開啟後這個熱鍵 (以及快速跳轉、內嵌搜尋叫出)會退出下面<a href="#process-blacklist">處理程序黑名單</a>裡說的那套全螢幕自動放行機制。</li><li><strong>快速跳轉</strong> —— 預設 <code>Ctrl+G</code>。</li></ul><p><strong>功能鍵</strong>分組:</p><ul><li>下一項(<code>Ctrl+N</code>)、上一項(<code>Ctrl+P</code>)、跳到結果的輔助鍵(預設 <code>Ctrl</code>，配合數字 1–9)、開啟動作選單(<code>Ctrl+O</code>)、從選取項補全(<code>Ctrl+Tab</code>)、QuickLook(<code>Alt+P</code>)、上/下一條關鍵字歷史 (<code>Alt+Up</code> / <code>Alt+Down</code>)、刪除目前關鍵字歷史(<code>Ctrl+Delete</code>)、開啟完整視窗(預設 <code>Ctrl+F</code>—— 直接開啟完整視窗並帶上目前搜尋內容,效果跟左鍵點擊快速視窗自帶的圖示、再選「顯示主視窗」一樣, 只是省了點選單這一步)、開啟傳送視窗(預設 <code>Ctrl+S</code>——開啟傳送檔案/文字至 LocalSend 裝置的視窗)。</li><li>這裡的每個錄製控制項都能接受任意按鍵或組合——包括裸 <code>Tab</code> 這種鍵——錄製下來的綁定會優先於該按鍵原本可能存在的任何硬編碼含義。</li></ul><p><strong>快速導覽</strong>分組:</p><ul><li><strong>在空白處按兩下左鍵</strong> —— 核取方塊，預設開啟。</li><li><strong>在空白處點擊中鍵</strong> —— 核取方塊，預設開啟。</li></ul><h2 id="外掛動作" tabindex="-1">外掛動作 <a class="header-anchor" href="#外掛動作" aria-label="Permalink to &quot;外掛動作&quot;">​</a></h2><p>每個外掛註冊的動作都有一條(比如複製路徑、以系統管理員身分執行)，按註冊它們的外掛分組，各自帶獨立的熱鍵錄製控制項。改之前會一直沿用外掛自己建議的預設值。</p><h2 id="process-blacklist" tabindex="-1">處理程序黑名單 <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;處理程序黑名單 {#process-blacklist}&quot;">​</a></h2><p>新增可執行檔名稱(例如 <code>game.exe</code>)，當它處於前景時，會完全放行 Lertaro 的全域熱鍵、按鍵攔截，以及快速導覽的按兩下/中鍵滑鼠觸發。不區分大小寫，<code>.exe</code> 副檔名可省略。和<strong>索引</strong>裡的排除規則一樣支援單條新增/批次編輯:一個單條輸入框配<strong>新增處理程序</strong>按鈕，一個現有項目清單，以及一個批次文字框配<strong>產生文字</strong> / <strong>套用文字</strong>按鈕。</p><p>這正是解決全螢幕遊戲或其他會獨佔鍵盤原始輸入的應用程式與熱鍵衝突的方法——見<a href="./../troubleshooting.html#全域熱鍵沒有反應">疑難排解</a>。任何真正全螢幕的前景應用程式都會自動取得同樣的效果，不需要在這裡手動新增——除非<strong>全域</strong>分組裡「顯示/隱藏快速搜尋」旁邊的<strong>全螢幕應用程式聚焦時仍然回應</strong>被開啟，那樣會整體退出這套自動豁免。無論哪種情況，目前作用中視窗如果是檔案選擇器，都會被豁免，快速導覽依然可以正常使用。</p>',14)])])}const u=o(a,[["render",l]]);export{p as __pageData,u as default};
